
const express = require("express");
const Patient = require("../models/Patient");
const generatePatientNumber = require("../utils/generatePatientNumber");
const findPossibleDuplicates = require("../utils/findPossibleDuplicates");
const PatientReview = require("../models/PatientReview");

const router = express.Router();

// Temporary local-development Patient Registration API
router.post("/", async (req, res) => {
  try {
    const {
      fullName,
      dateOfBirth,
      sex,
      phone,
      address
    } = req.body;

    // Patient numbers must be generated by the backend.
    if (req.body.patientNumber !== undefined) {
      return res.status(400).json({
        success: false,
        message: "Patient number is generated automatically"
      });
    }

    // Create the patient document in memory.
    const patient = new Patient({
      fullName,
      dateOfBirth,
      sex,
      phone,
      address
    });

    // Validate supplied fields before accessing the counter.
    await patient.validate([
      "fullName",
      "dateOfBirth",
      "sex",
      "phone",
      "address"
    ]);

    // Check for existing patients with matching details.
    const possibleDuplicates = await findPossibleDuplicates(
      patient.fullName,
      patient.dateOfBirth
    );

    // Pause registration when a possible match exists.
    
if (possibleDuplicates.length > 0) {

  // Look for an existing pending review for the same candidate.
  const existingReview = await PatientReview.findOne({
    "candidatePatient.fullName": patient.fullName,
    "candidatePatient.dateOfBirth": patient.dateOfBirth,
    status: "PENDING"
  }).collation({ locale: "en", strength: 2 });

  // Create a review only if a pending review was not found.
  if (!existingReview) {
    await PatientReview.create({
      candidatePatient: {
        fullName: patient.fullName,
        dateOfBirth: patient.dateOfBirth,
        phone: patient.phone
      },

      possibleMatchIds: possibleDuplicates.map(
        (match) => match._id
      ),

      status: "PENDING"
    });
  }

  return res.status(409).json({
    success: false,
    code: "POSSIBLE_DUPLICATE",
    message: "Possible existing patient found. Staff review required.",
    requiresReview: true,
    matchCount: possibleDuplicates.length
  });
}


    // Generate the next unique patient number.
    patient.patientNumber = await generatePatientNumber();

    // Save only after validation and duplicate screening.
    await patient.save();

    return res.status(201).json({
      success: true,
      message: "Patient registered successfully",
      patientId: patient._id,
      patientNumber: patient.patientNumber
    });

  
  } catch (error) {
    if (error.name === "ValidationError") {
      return res.status(400).json({
        success: false,
        message: "Invalid patient information"
      });
    }

    // Handle two requests trying to create the same
    // pending patient review simultaneously.
    if (
      error.code === 11000 &&
      error.message?.includes("unique_pending_patient_review")
    ) {
      return res.status(409).json({
        success: false,
        code: "POSSIBLE_DUPLICATE",
        message: "Possible existing patient found. Staff review required.",
        requiresReview: true
      });
    }

    // Handle other MongoDB duplicate-key conflicts.
    if (error.code === 11000) {
      return res.status(409).json({
        success: false,
        message: "A unique database value already exists"
      });
    }

    console.error("Patient registration failed:", error.name);

    return res.status(500).json({
      success: false,
      message: "Unable to register patient"
    });
}});

module.exports = router;
